import numpy as np, pandas as pd

# Low-speed branch fit using certified-range experiments only
low = pd.DataFrame({
    "speed": [0.8, 0.9, 1.0, 1.1, 1.2],
    "mean":  [5.366667, 5.35, 6.5, 7.0125, 7.116667]
})
b_low, a_low = np.polyfit(low["speed"], low["mean"], 1)  # mean = b*s + a

mu12 = b_low*1.2 + a_low

# High-speed branch constrained to pass through (1.2, mu12), fit slope from 1.28 and 1.4
high = pd.DataFrame({
    "speed": [1.28, 1.4],
    "mean":  [11.1125, 20.728571428571428]
})
dx = high["speed"].to_numpy() - 1.2
dy = high["mean"].to_numpy() - mu12
slope_high = float((dx @ dy) / (dx @ dx))

print("low branch coeffs: slope, intercept =", b_low, a_low)
print("mu at 1.2 from low branch =", mu12)
print("high branch slope from 1.2 =", slope_high)
for s in [0.8,0.9,1.0,1.1,1.2,1.28,1.4]:
    mu = (b_low*s + a_low) if s <= 1.2 else (mu12 + slope_high*(s-1.2))
    print(f"speed={s:.2f}, mu_hat={mu:.4f}")

code = f'''
import numpy as np
import pandas as pd

def model(regime, n, seed):
    rng = np.random.default_rng(seed)
    speed = float(regime.config.get("speed", 1.0))
    b_low = {float(b_low)!r}
    a_low = {float(a_low)!r}
    mu12 = {float(mu12)!r}
    slope_high = {float(slope_high)!r}
    if speed <= 1.2:
        mu = b_low * speed + a_low
    else:
        mu = mu12 + slope_high * (speed - 1.2)
    mu = max(mu, 1e-9)
    y = rng.poisson(mu, size=n)
    return pd.DataFrame({{"unit_id": np.arange(n), "y": y.astype(int)}})
'''
env.register_model(code)
print("\nregistered updated piecewise-Poisson model for upcoming pilot")
print("budget now:", env.describe()["budget_remaining"])
